mapper.select:
select
from blog left join category on blog.category_id = category.id left join user on blog.user_id = user.id
and (blog.title like concat('%', #{keyword}, '%') or blog.descr like concat('%', #{keyword}, '%') or blog.tags like concat('%', #{keyword}, '%'))
and blog.category_id = #{categoryId}
order by blog.read_count desc limit #{limit}
